import json, os, random

def L(sp, v, el, en): return {"speaker": sp, "voice": v, "el": el, "en": en}
def Q(q, opts, ans, why): return {"q": q, "options": opts, "answer": opts[ans], "why": why}

ITEMS = []

ITEMS.append({
 "id": "l44-ann-episkeptirio", "title": "Ώρες επισκεπτηρίου", "title_en": "Hospital visiting hours", "type": "announcement", "level": "B2",
 "context_el": "Θα ακούσετε μια ανακοίνωση από τα μεγάφωνα ενός νοσοκομείου.",
 "script": [
  L("Εκφωνήτρια", "f", "Αγαπητοί επισκέπτες, σας ενημερώνουμε ότι από τη Δευτέρα αλλάζει το ωράριο του επισκεπτηρίου. Οι επισκέψεις θα επιτρέπονται καθημερινά από τις έξι έως τις οχτώ το απόγευμα, ενώ τα Σαββατοκύριακα και από τις έντεκα έως τη μία το μεσημέρι.", "Dear visitors, we inform you that from Monday the visiting hours are changing. Visits will be allowed daily from six to eight in the evening, and at weekends also from eleven to one at midday."),
  L("Εκφωνήτρια", "f", "Για την προστασία των ασθενών, σε κάθε θάλαμο επιτρέπεται ένας μόνο επισκέπτης ανά ασθενή. Παιδιά κάτω των δώδεκα ετών δεν επιτρέπεται να μπαίνουν στις κλινικές. Στη Μονάδα Εντατικής Θεραπείας οι επισκέψεις γίνονται μόνο ύστερα από συνεννόηση με τους γιατρούς.", "To protect patients, only one visitor per patient is allowed in each ward. Children under twelve are not allowed into the clinics. In the Intensive Care Unit, visits take place only by arrangement with the doctors."),
  L("Εκφωνήτρια", "f", "Παρακαλούμε να μη φέρνετε λουλούδια στους θαλάμους και να πλένετε τα χέρια σας με το αντισηπτικό στην είσοδο κάθε κλινικής. Για πληροφορίες σχετικά με την κατάσταση των ασθενών, απευθυνθείτε στο γραφείο νοσηλευτών του κάθε ορόφου. Σας ευχαριστούμε για τη συνεργασία.", "Please do not bring flowers into the wards, and wash your hands with the sanitiser at the entrance of each clinic. For information about patients' condition, please ask at the nurses' office on each floor. Thank you for your cooperation."),
 ],
 "questions": [
  Q("Πότε θα επιτρέπονται οι επισκέψεις τις καθημερινές;", ["Από τις έντεκα έως τη μία", "Από τις έξι έως τις οχτώ το απόγευμα", "Όλη μέρα", "Μόνο το πρωί"], 1, "Οι επισκέψεις θα επιτρέπονται καθημερινά από τις έξι έως τις οχτώ το απόγευμα"),
  Q("Πόσοι επισκέπτες επιτρέπονται ανά ασθενή;", ["Δύο", "Ένας μόνο", "Όσοι θέλουν", "Κανένας"], 1, "σε κάθε θάλαμο επιτρέπεται ένας μόνο επισκέπτης ανά ασθενή"),
  Q("Πού πρέπει να απευθυνθούν οι επισκέπτες για πληροφορίες για την κατάσταση των ασθενών;", ["Στη ρεσεψιόν της εισόδου", "Στο γραφείο νοσηλευτών του κάθε ορόφου", "Στον διευθυντή του νοσοκομείου", "Τηλεφωνικά στο κέντρο"], 1, "απευθυνθείτε στο γραφείο νοσηλευτών του κάθε ορόφου"),
 ],
 "gloss": {"επισκεπτηρίου": "επισκεπτήριο — visiting hours", "ωράριο": "ωράριο — schedule, hours", "θάλαμο": "θάλαμος — (hospital) ward", "ασθενή": "ασθενής — patient", "κλινικές": "κλινική — clinic, hospital department", "Μονάδα Εντατικής Θεραπείας": "Μονάδα Εντατικής Θεραπείας — Intensive Care Unit", "συνεννόηση": "συνεννόηση — arrangement, agreement", "αντισηπτικό": "αντισηπτικό — sanitiser, antiseptic", "απευθυνθείτε": "απευθύνομαι — to apply to, ask", "νοσηλευτών": "νοσηλευτής — nurse"},
})

ITEMS.append({
 "id": "l44-vm-estiatorio", "title": "Επιβεβαίωση κράτησης", "title_en": "A booking confirmation", "type": "voicemail", "level": "B2",
 "context_el": "Θα ακούσετε ένα μήνυμα από ένα εστιατόριο στον τηλεφωνητή σας.",
 "script": [
  L("Υπάλληλος", "f", "Καλησπέρα σας, κυρία Μαυρίδου, από το εστιατόριο «Η Αυλή» σας τηλεφωνώ. Θέλουμε να επιβεβαιώσουμε την κράτησή σας για το Σάββατο στις εννέα το βράδυ, για δώδεκα άτομα, για τα γενέθλια της μητέρας σας.", "Good evening, Mrs Mavridou, I'm calling from \"I Avli\" restaurant. We'd like to confirm your booking for Saturday at nine in the evening, for twelve people, for your mother's birthday."),
  L("Υπάλληλος", "f", "Επειδή είστε μεγάλη παρέα, σας έχουμε κρατήσει το τραπέζι στην αυλή, κάτω από την κληματαριά. Αν όμως ο καιρός χαλάσει, θα σας βάλουμε στη σάλα του πρώτου ορόφου. Θα θέλαμε επίσης να μας πείτε αν κάποιος από τους καλεσμένους έχει αλλεργίες ή ακολουθεί ειδική διατροφή, ώστε να ενημερώσουμε τον σεφ.", "Because you're a large group, we've reserved the table in the courtyard for you, under the vine arbour. But if the weather turns bad, we'll put you in the first-floor dining room. We'd also like you to tell us whether any of the guests has allergies or follows a special diet, so that we can let the chef know."),
  L("Υπάλληλος", "f", "Για την τούρτα που θα φέρετε, δεν υπάρχει πρόβλημα· θα τη φυλάξουμε στο ψυγείο και θα τη σερβίρουμε με κεριά στο τέλος. Παρακαλώ επιβεβαιώστε μας μέχρι την Πέμπτη, γιατί για παρέες άνω των δέκα ατόμων ζητάμε προκαταβολή πενήντα ευρώ. Ευχαριστώ, καλό βράδυ.", "As for the cake you'll be bringing, there's no problem; we'll keep it in the fridge and serve it with candles at the end. Please confirm with us by Thursday, because for groups of more than ten people we ask for a fifty-euro deposit. Thank you, good evening."),
 ],
 "questions": [
  Q("Πού θα κάτσει η παρέα, αν χαλάσει ο καιρός;", ["Στην αυλή κάτω από ομπρέλες", "Στη σάλα του πρώτου ορόφου", "Σε άλλο εστιατόριο", "Στο μπαρ"], 1, "Αν όμως ο καιρός χαλάσει, θα σας βάλουμε στη σάλα του πρώτου ορόφου"),
  Q("Γιατί ρωτάει η υπάλληλος για αλλεργίες;", ["Για να υπολογίσει τον λογαριασμό", "Για να ενημερώσει τον σεφ", "Επειδή το απαιτεί ο νόμος", "Για να αλλάξει το τραπέζι"], 1, "ώστε να ενημερώσουμε τον σεφ"),
  Q("Γιατί πρέπει η κυρία Μαυρίδου να επιβεβαιώσει μέχρι την Πέμπτη;", ["Επειδή το εστιατόριο κλείνει την Παρασκευή", "Επειδή για παρέες άνω των δέκα ατόμων ζητούν προκαταβολή", "Επειδή αλλιώς δεν θα έχουν τούρτα", "Επειδή ο σεφ λείπει"], 1, "για παρέες άνω των δέκα ατόμων ζητάμε προκαταβολή πενήντα ευρώ"),
 ],
 "gloss": {"εστιατόριο": "εστιατόριο — restaurant", "να επιβεβαιώσουμε": "επιβεβαιώνω — to confirm", "κράτησή": "κράτηση — booking", "παρέα": "παρέα — group (of friends), company", "αυλή": "αυλή — courtyard", "κληματαριά": "κληματαριά — vine arbour", "σάλα": "σάλα — dining room, hall", "καλεσμένους": "καλεσμένος — guest", "ειδική διατροφή": "ειδική διατροφή — special diet", "προκαταβολή": "προκαταβολή — deposit"},
})

ITEMS.append({
 "id": "l44-dia-exochiko", "title": "Ένα σπίτι για τις διακοπές", "title_en": "A holiday house", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε έναν άντρα που τηλεφωνεί σε μια ιδιοκτήτρια για να νοικιάσει ένα εξοχικό σπίτι στη Χαλκιδική.",
 "script": [
  L("Πελάτης", "m", "Καλημέρα σας. Είδα την αγγελία σας για το σπίτι στη Σιθωνία. Θα θέλαμε να το νοικιάσουμε για δέκα μέρες, από τις δεκαπέντε Ιουλίου. Είμαστε δύο οικογένειες, τέσσερις ενήλικες και τρία παιδιά. Χωράμε;", "Good morning. I saw your ad for the house in Sithonia. We'd like to rent it for ten days, from the fifteenth of July. We're two families, four adults and three children. Is there room for us?"),
  L("Ιδιοκτήτρια", "f", "Χωράτε άνετα. Το σπίτι έχει τρία υπνοδωμάτια, δύο μπάνια και μεγάλη βεράντα με θέα στη θάλασσα. Η παραλία είναι πέντε λεπτά με τα πόδια. Τον Ιούλιο η τιμή είναι εκατόν πενήντα ευρώ τη βραδιά, και ζητάω προκαταβολή το τριάντα τοις εκατό για να κλείσει η κράτηση.", "There's plenty of room. The house has three bedrooms, two bathrooms and a big veranda with a sea view. The beach is five minutes on foot. In July the price is a hundred and fifty euros a night, and I ask for a thirty per cent deposit to secure the booking."),
  L("Πελάτης", "m", "Μάλιστα. Έχουμε και έναν σκύλο, μικρόσωμο και πολύ ήσυχο. Επιτρέπονται τα κατοικίδια; Και υπάρχει κλιματισμός;", "I see. We also have a dog, small and very quiet. Are pets allowed? And is there air conditioning?"),
  L("Ιδιοκτήτρια", "f", "Κλιματιστικά υπάρχουν σε όλα τα δωμάτια. Τα κατοικίδια τα δεχόμαστε, αλλά με δύο όρους: ο σκύλος δεν ανεβαίνει στα κρεβάτια και στους καναπέδες, και χρεώνουμε τριάντα ευρώ επιπλέον για τον καθαρισμό στο τέλος. Αν συμφωνείτε, σας στέλνω τα στοιχεία του λογαριασμού για την προκαταβολή.", "There are air conditioners in all the rooms. We accept pets, but on two conditions: the dog doesn't get on the beds and sofas, and we charge thirty euros extra for the cleaning at the end. If you agree, I'll send you the account details for the deposit."),
 ],
 "questions": [
  Q("Πόσο απέχει η παραλία από το σπίτι;", ["Δέκα λεπτά με το αυτοκίνητο", "Πέντε λεπτά με τα πόδια", "Είναι ακριβώς μπροστά στο σπίτι", "Μισή ώρα με τα πόδια"], 1, "Η παραλία είναι πέντε λεπτά με τα πόδια"),
  Q("Τι χρειάζεται για να κλείσει η κράτηση;", ["Μια φωτοτυπία της ταυτότητας", "Προκαταβολή το τριάντα τοις εκατό", "Ολόκληρο το ποσό από πριν", "Ένα συμβόλαιο στον συμβολαιογράφο"], 1, "ζητάω προκαταβολή το τριάντα τοις εκατό για να κλείσει η κράτηση"),
  Q("Με ποιους όρους δέχεται η ιδιοκτήτρια τον σκύλο;", ["Μόνο αν μένει στη βεράντα", "Να μην ανεβαίνει σε κρεβάτια και καναπέδες και να πληρώσουν τριάντα ευρώ για καθαρισμό", "Μόνο αν είναι εμβολιασμένος", "Δεν δέχεται κανέναν σκύλο"], 1, "ο σκύλος δεν ανεβαίνει στα κρεβάτια και στους καναπέδες, και χρεώνουμε τριάντα ευρώ επιπλέον για τον καθαρισμό"),
 ],
 "gloss": {"εξοχικό": "εξοχικό — holiday home, country house", "αγγελία": "αγγελία — (classified) ad", "ενήλικες": "ενήλικας — adult", "Χωράμε": "χωράω — to fit, have room", "υπνοδωμάτια": "υπνοδωμάτιο — bedroom", "βεράντα": "βεράντα — veranda", "μικρόσωμο": "μικρόσωμος — small (of body size)", "κατοικίδια": "κατοικίδιο — pet", "χρεώνουμε": "χρεώνω — to charge", "στοιχεία του λογαριασμού": "στοιχεία λογαριασμού — account details"},
})

ITEMS.append({
 "id": "l44-dia-thermokrasia", "title": "Η θερμοκρασία στο γραφείο", "title_en": "The temperature in the office", "type": "dialogue", "level": "B2",
 "context_el": "Θα ακούσετε δύο συναδέλφους που διαφωνούν για τη θερμοκρασία του κλιματιστικού στο γραφείο τους.",
 "script": [
  L("Σοφία", "f", "Κώστα, συγγνώμη, μπορούμε να ανεβάσουμε λίγο τη θερμοκρασία; Το κλιματιστικό είναι στους δεκαεννιά βαθμούς και έχω παγώσει. Φοράω ζακέτα μέσα στον Ιούλιο!", "Kostas, sorry, can we turn the temperature up a bit? The air conditioning is at nineteen degrees and I'm frozen. I'm wearing a cardigan in July!"),
  L("Κώστας", "m", "Σε καταλαβαίνω, αλλά εγώ κάθομαι δίπλα στο παράθυρο, και ο ήλιος με χτυπάει όλο το απόγευμα. Αν το ανεβάσουμε, θα λιώσω. Επιπλέον, φοράω πουκάμισο και γραβάτα, γιατί έχω συναντήσεις με πελάτες.", "I understand, but I sit next to the window, and the sun beats down on me all afternoon. If we turn it up, I'll melt. Besides, I'm wearing a shirt and tie, because I have meetings with clients."),
  L("Σοφία", "f", "Ξέρεις ότι η εταιρεία έστειλε email και ζήτησε να είναι τα κλιματιστικά στους είκοσι έξι, για να εξοικονομούμε ενέργεια; Και πέρα από αυτό, η διαφορά με τη θερμοκρασία έξω είναι τόσο μεγάλη, που κάθε φορά που βγαίνω κρυώνω.", "Do you know the company sent an email asking for the air conditioners to be at twenty-six, to save energy? And apart from that, the difference from the temperature outside is so big that every time I go out I catch a chill."),
  L("Κώστας", "m", "Εντάξει, έχεις δίκιο. Ας κάνουμε έναν συμβιβασμό: το βάζουμε στους είκοσι τέσσερις, εγώ κατεβάζω τα στόρια το απόγευμα, και ρωτάμε τον υπεύθυνο αν μπορώ να αλλάξω θέση, να κάτσω πιο μέσα, μακριά από το παράθυρο.", "OK, you're right. Let's make a compromise: we set it to twenty-four, I lower the blinds in the afternoon, and we ask the manager whether I can change desks and sit further in, away from the window."),
 ],
 "questions": [
  Q("Γιατί ο Κώστας δεν θέλει να ανεβεί η θερμοκρασία;", ["Επειδή είναι άρρωστος", "Επειδή κάθεται δίπλα στο παράθυρο και τον χτυπάει ο ήλιος", "Επειδή του το είπε ο υπεύθυνος", "Επειδή το κλιματιστικό είναι χαλασμένο"], 1, "κάθομαι δίπλα στο παράθυρο, και ο ήλιος με χτυπάει όλο το απόγευμα"),
  Q("Τι ζήτησε η εταιρεία με email;", ["Να κλείνουν τα παράθυρα", "Να είναι τα κλιματιστικά στους είκοσι έξι βαθμούς", "Να φορούν όλοι γραβάτα", "Να δουλεύουν από το σπίτι τον Ιούλιο"], 1, "ζήτησε να είναι τα κλιματιστικά στους είκοσι έξι, για να εξοικονομούμε ενέργεια"),
  Q("Ποιος είναι ο συμβιβασμός που προτείνει ο Κώστας;", ["Να κλείσουν το κλιματιστικό", "Είκοσι τέσσερις βαθμοί, στόρια το απόγευμα και αλλαγή θέσης", "Να αγοράσει η Σοφία θερμάστρα", "Να δουλεύουν σε διαφορετικές ώρες"], 1, "το βάζουμε στους είκοσι τέσσερις, εγώ κατεβάζω τα στόρια το απόγευμα"),
 ],
 "gloss": {"θερμοκρασία": "θερμοκρασία — temperature", "κλιματιστικό": "κλιματιστικό — air conditioner", "έχω παγώσει": "παγώνω — to freeze", "ζακέτα": "ζακέτα — cardigan", "θα λιώσω": "λιώνω — to melt", "γραβάτα": "γραβάτα — tie", "να εξοικονομούμε": "εξοικονομώ — to save (energy, money)", "συμβιβασμό": "συμβιβασμός — compromise", "στόρια": "στόρι — blind", "υπεύθυνο": "υπεύθυνος — manager, person in charge"},
})

ITEMS.append({
 "id": "l44-mono-mpouzouki", "title": "Μπουζούκι στα εξήντα", "title_en": "Bouzouki at sixty", "type": "monologue", "level": "B2",
 "context_el": "Θα ακούσετε έναν συνταξιούχο που μιλάει σε μια ραδιοφωνική εκπομπή για το πώς έμαθε μπουζούκι.",
 "script": [
  L("Παναγιώτης", "m", "Όλη μου τη ζωή ήθελα να παίζω μπουζούκι. Όταν ήμουν παιδί, ο πατέρας μου έλεγε ότι η μουσική δεν είναι δουλειά, και έπρεπε να βοηθάω στο μαγαζί. Μετά ήρθαν η δουλειά στην τράπεζα, τα παιδιά, οι υποχρεώσεις. Πάντα έλεγα «του χρόνου».", "All my life I wanted to play the bouzouki. When I was a child, my father said music isn't a job, and I had to help in the shop. Then came the job at the bank, the children, the obligations. I always said 'next year'."),
  L("Παναγιώτης", "m", "Όταν βγήκα στη σύνταξη, στα εξήντα, η κόρη μου μού έκανε δώρο ένα μπουζούκι και μια κάρτα με τρεις μήνες μαθήματα σε ένα ωδείο. Την πρώτη μέρα ντράπηκα πολύ. Οι άλλοι μαθητές ήταν δεκαπέντε χρονών και τα δάχτυλά τους έτρεχαν πάνω στις χορδές, ενώ τα δικά μου ήταν σκληρά σαν ξύλο.", "When I retired, at sixty, my daughter gave me a bouzouki as a present and a card for three months of lessons at a music school. The first day I was very embarrassed. The other students were fifteen and their fingers ran over the strings, while mine were stiff as wood."),
  L("Παναγιώτης", "m", "Ο δάσκαλός μου, όμως, μου είπε κάτι που δεν θα ξεχάσω: «Τα παιδιά έχουν γρήγορα δάχτυλα, εσύ έχεις κάτι που δεν διδάσκεται: έχεις ακούσει αυτά τα τραγούδια μια ζωή». Μελετούσα κάθε μέρα μία ώρα. Σήμερα, τέσσερα χρόνια μετά, παίζω με μια μικρή κομπανία σε πανηγύρια και σε γάμους. Ο πατέρας μου δεν πρόλαβε να με ακούσει, αλλά τα εγγόνια μου χορεύουν όταν παίζω.", "But my teacher told me something I won't forget: 'The kids have fast fingers; you have something that can't be taught: you've been listening to these songs all your life.' I practised an hour every day. Today, four years later, I play with a small band at village festivals and weddings. My father didn't live to hear me, but my grandchildren dance when I play."),
 ],
 "questions": [
  Q("Γιατί ο Παναγιώτης δεν έμαθε μπουζούκι ως παιδί;", ["Επειδή δεν είχε χρήματα για μπουζούκι", "Επειδή ο πατέρας του έλεγε ότι η μουσική δεν είναι δουλειά", "Επειδή δεν υπήρχε ωδείο", "Επειδή δεν τον ενδιέφερε"], 1, "ο πατέρας μου έλεγε ότι η μουσική δεν είναι δουλειά"),
  Q("Γιατί ντράπηκε την πρώτη μέρα στο ωδείο;", ["Επειδή άργησε", "Επειδή οι άλλοι μαθητές ήταν πολύ νεότεροι και πιο γρήγοροι", "Επειδή ξέχασε το μπουζούκι", "Επειδή ο δάσκαλος τον μάλωσε"], 1, "Οι άλλοι μαθητές ήταν δεκαπέντε χρονών και τα δάχτυλά τους έτρεχαν πάνω στις χορδές"),
  Q("Τι κάνει σήμερα ο Παναγιώτης;", ["Διδάσκει μπουζούκι σε παιδιά", "Παίζει με μια κομπανία σε πανηγύρια και γάμους", "Έχει σταματήσει να παίζει", "Παίζει μόνο στο σπίτι"], 1, "παίζω με μια μικρή κομπανία σε πανηγύρια και σε γάμους"),
 ],
 "gloss": {"μπουζούκι": "μπουζούκι — bouzouki", "συνταξιούχο": "συνταξιούχος — pensioner, retiree", "υποχρεώσεις": "υποχρέωση — obligation", "βγήκα στη σύνταξη": "βγαίνω στη σύνταξη — to retire", "ωδείο": "ωδείο — music school, conservatory", "ντράπηκα": "ντρέπομαι — to be embarrassed, shy", "χορδές": "χορδή — string", "δεν διδάσκεται": "διδάσκομαι — to be taught", "κομπανία": "κομπανία — (folk) band", "πανηγύρια": "πανηγύρι — village festival"},
})

ITEMS.append({
 "id": "l44-rep-epistrofi-mpoukalion", "title": "Επιστροφή για τα μπουκάλια", "title_en": "Money back for bottles", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ για ένα πιλοτικό πρόγραμμα επιστροφής πλαστικών μπουκαλιών σε σούπερ μάρκετ.",
 "script": [
  L("Δημοσιογράφος", "f", "Στην είσοδο ενός σούπερ μάρκετ στο Περιστέρι, μια μεγάλη πράσινη μηχανή «καταπίνει» πλαστικά μπουκάλια και αλουμινένια κουτάκια. Για κάθε συσκευασία που επιστρέφει ο καταναλωτής, η μηχανή τυπώνει ένα κουπόνι αξίας δέκα λεπτών, που μπορεί να χρησιμοποιηθεί στο ταμείο.", "At the entrance of a supermarket in Peristeri, a big green machine 'swallows' plastic bottles and aluminium cans. For each container the customer returns, the machine prints a voucher worth ten cents, which can be used at the till."),
  L("Δημοσιογράφος", "f", "Η ιδέα δεν είναι καινούργια. Σε χώρες όπως η Γερμανία και η Νορβηγία, συστήματα επιστροφής εγγύησης λειτουργούν εδώ και χρόνια, και πάνω από το ενενήντα τοις εκατό των μπουκαλιών επιστρέφεται. Στην Ελλάδα, αντίθετα, πολλά πλαστικά μπουκάλια καταλήγουν ακόμα σε χωματερές ή στη θάλασσα.", "The idea isn't new. In countries such as Germany and Norway, deposit-return systems have been working for years, and over ninety per cent of bottles are returned. In Greece, by contrast, many plastic bottles still end up in landfills or in the sea."),
  L("Δημοσιογράφος", "f", "Οι πελάτες με τους οποίους μιλήσαμε δείχνουν ενθουσιασμένοι. «Μαζεύω τα μπουκάλια όλης της πολυκατοικίας», μας λέει μια συνταξιούχος, «και με τα κουπόνια αγοράζω τον καφέ του μήνα». Κάποιοι, πάντως, παραπονιούνται ότι η μηχανή δεν δέχεται τσαλακωμένα μπουκάλια, γιατί πρέπει να διαβάσει το barcode. Αν το πρόγραμμα πετύχει, θα επεκταθεί σε όλη τη χώρα.", "The customers we spoke to seem enthusiastic. 'I collect the bottles of the whole building,' a pensioner tells us, 'and with the vouchers I buy my coffee for the month.' Some, however, complain that the machine won't accept crushed bottles, because it has to read the barcode. If the programme succeeds, it will be extended to the whole country."),
 ],
 "questions": [
  Q("Τι παίρνει ο καταναλωτής για κάθε συσκευασία που επιστρέφει;", ["Ένα δωρεάν μπουκάλι νερό", "Ένα κουπόνι δέκα λεπτών", "Πόντους σε μια εφαρμογή", "Ένα ευρώ σε μετρητά"], 1, "η μηχανή τυπώνει ένα κουπόνι αξίας δέκα λεπτών"),
  Q("Τι ισχύει σε χώρες όπως η Γερμανία και η Νορβηγία;", ["Δεν υπάρχουν πλαστικά μπουκάλια", "Επιστρέφεται πάνω από το ενενήντα τοις εκατό των μπουκαλιών", "Τα μπουκάλια καίγονται", "Το πρόγραμμα σταμάτησε"], 1, "πάνω από το ενενήντα τοις εκατό των μπουκαλιών επιστρέφεται"),
  Q("Για ποιο πράγμα παραπονιούνται κάποιοι πελάτες;", ["Ότι το κουπόνι αξίζει πολύ λίγο", "Ότι η μηχανή δεν δέχεται τσαλακωμένα μπουκάλια", "Ότι η μηχανή είναι πάντα χαλασμένη", "Ότι η ουρά είναι μεγάλη"], 1, "η μηχανή δεν δέχεται τσαλακωμένα μπουκάλια, γιατί πρέπει να διαβάσει το barcode"),
 ],
 "gloss": {"πιλοτικό": "πιλοτικός — pilot (adj.)", "αλουμινένια": "αλουμινένιος — aluminium (adj.)", "κουτάκια": "κουτάκι — can", "συσκευασία": "συσκευασία — package, container", "κουπόνι": "κουπόνι — voucher", "ταμείο": "ταμείο — till, checkout", "επιστροφής εγγύησης": "σύστημα επιστροφής εγγύησης — deposit-return system", "χωματερές": "χωματερή — landfill", "τσαλακωμένα": "τσαλακωμένος — crushed, crumpled", "θα επεκταθεί": "επεκτείνομαι — to be extended"},
})

ITEMS.append({
 "id": "l44-rep-askisi-seismou", "title": "Άσκηση σεισμού στο σχολείο", "title_en": "An earthquake drill at school", "type": "report", "level": "B2",
 "context_el": "Θα ακούσετε ένα ρεπορτάζ από μια άσκηση σεισμού σε ένα δημοτικό σχολείο.",
 "script": [
  L("Δημοσιογράφος", "m", "Δέκα και μισή το πρωί σε ένα δημοτικό σχολείο της Πάτρας. Ξαφνικά ακούγεται ένα δυνατό κουδούνι, που χτυπάει διακεκομμένα. Μέσα σε λίγα δευτερόλεπτα, τα παιδιά έχουν μπει κάτω από τα θρανία και κρατούν σφιχτά τα πόδια τους, όπως έχουν μάθει.", "Half past ten in the morning at a primary school in Patras. Suddenly a loud bell is heard, ringing intermittently. Within a few seconds, the children have got under their desks and are holding the legs tightly, as they've learned."),
  L("Δημοσιογράφος", "m", "Όταν το κουδούνι σταματά, οι δάσκαλοι οδηγούν τις τάξεις, με ήρεμο ρυθμό και χωρίς να τρέχουν, στο προαύλιο, μακριά από το κτίριο και από τις κολόνες του ρεύματος. Εκεί η διευθύντρια μετράει τα παιδιά κάθε τάξης με βάση έναν κατάλογο. Όλη η εκκένωση ολοκληρώθηκε σε λιγότερο από τρία λεπτά.", "When the bell stops, the teachers lead the classes, at a calm pace and without running, into the playground, away from the building and the electricity poles. There the head teacher counts the children of each class against a list. The whole evacuation was completed in less than three minutes."),
  L("Δημοσιογράφος", "m", "Τέτοιες ασκήσεις γίνονται υποχρεωτικά δύο φορές τον χρόνο σε όλα τα σχολεία της χώρας. «Η Ελλάδα είναι από τις πιο σεισμογενείς χώρες της Ευρώπης», εξηγεί η διευθύντρια. «Θέλουμε τα παιδιά να ξέρουν τι να κάνουν χωρίς να το σκεφτούν, ώστε να μην πανικοβληθούν σε έναν πραγματικό σεισμό. Και πολλά από αυτά γυρίζουν σπίτι και μαθαίνουν τους γονείς τους τι πρέπει να κάνουν.»", "Such drills are compulsory twice a year in all the country's schools. 'Greece is one of the most earthquake-prone countries in Europe,' the head teacher explains. 'We want the children to know what to do without thinking, so that they don't panic in a real earthquake. And many of them go home and teach their parents what to do.'"),
 ],
 "questions": [
  Q("Τι κάνουν τα παιδιά όταν ακούν το κουδούνι;", ["Τρέχουν αμέσως έξω", "Μπαίνουν κάτω από τα θρανία και κρατούν τα πόδια τους", "Στέκονται δίπλα στα παράθυρα", "Τηλεφωνούν στους γονείς τους"], 1, "τα παιδιά έχουν μπει κάτω από τα θρανία και κρατούν σφιχτά τα πόδια τους"),
  Q("Πόσο κράτησε η εκκένωση;", ["Δέκα λεπτά", "Λιγότερο από τρία λεπτά", "Μισή ώρα", "Ένα λεπτό ακριβώς"], 1, "Όλη η εκκένωση ολοκληρώθηκε σε λιγότερο από τρία λεπτά"),
  Q("Γιατί, κατά τη διευθύντρια, γίνονται αυτές οι ασκήσεις;", ["Για να χάνουν τα παιδιά μάθημα", "Για να ξέρουν τα παιδιά τι να κάνουν χωρίς να πανικοβληθούν", "Επειδή το ζήτησαν οι γονείς", "Επειδή το σχολείο είναι παλιό"], 1, "Θέλουμε τα παιδιά να ξέρουν τι να κάνουν χωρίς να το σκεφτούν, ώστε να μην πανικοβληθούν"),
 ],
 "gloss": {"άσκηση σεισμού": "άσκηση σεισμού — earthquake drill", "διακεκομμένα": "διακεκομμένα — intermittently", "θρανία": "θρανίο — school desk", "σφιχτά": "σφιχτά — tightly", "προαύλιο": "προαύλιο — school yard", "κολόνες του ρεύματος": "κολόνα του ρεύματος — electricity pole", "κατάλογο": "κατάλογος — list", "εκκένωση": "εκκένωση — evacuation", "σεισμογενείς": "σεισμογενής — earthquake-prone", "πανικοβληθούν": "πανικοβάλλομαι — to panic"},
})

ITEMS.append({
 "id": "l44-int-somelie", "title": "Μια νεαρή σομελιέ", "title_en": "A young sommelier", "type": "interview", "level": "B2",
 "context_el": "Θα ακούσετε μια συνέντευξη με μια σομελιέ που δουλεύει σε ένα εστιατόριο της Αθήνας.",
 "script": [
  L("Δημοσιογράφος", "m", "Πώς αποφασίσατε να γίνετε σομελιέ; Δεν είναι συνηθισμένο επάγγελμα για μια γυναίκα είκοσι επτά χρονών.", "How did you decide to become a sommelier? It's not a common profession for a woman of twenty-seven."),
  L("Σομελιέ", "f", "Η οικογένειά μου έχει αμπέλια στη Νεμέα, οπότε μεγάλωσα ανάμεσα σε βαρέλια. Σπούδασα όμως οικονομικά και δούλευα σε μια τράπεζα. Κάποια στιγμή κατάλαβα ότι μου έλειπε η μυρωδιά του τρύγου. Έκανα ένα πρόγραμμα σπουδών για σομελιέ στη Θεσσαλονίκη και μετά δούλεψα δύο χρόνια σε εστιατόρια στη Γαλλία.", "My family has vineyards in Nemea, so I grew up among barrels. But I studied economics and worked at a bank. At some point I realised I missed the smell of the grape harvest. I did a sommelier course in Thessaloniki and then worked for two years in restaurants in France."),
  L("Δημοσιογράφος", "m", "Πολλοί πελάτες φοβούνται τον κατάλογο των κρασιών. Τι τους συμβουλεύετε;", "Many customers are afraid of the wine list. What do you advise them?"),
  L("Σομελιέ", "f", "Να μη ντρέπονται να ρωτήσουν. Η δουλειά μου δεν είναι να τους πουλήσω το πιο ακριβό κρασί, αλλά να βρω αυτό που ταιριάζει στο φαγητό και στο γούστο τους. Συχνά προτείνω ελληνικές ποικιλίες που δεν ξέρουν, όπως το ασύρτικο ή το ξινόμαυρο. Και πάντα λέω ότι το καλύτερο κρασί είναι αυτό που πίνεις με καλή παρέα.", "Not to be shy about asking. My job isn't to sell them the most expensive wine, but to find the one that suits their food and their taste. I often suggest Greek varieties they don't know, like assyrtiko or xinomavro. And I always say the best wine is the one you drink in good company."),
 ],
 "questions": [
  Q("Τι έκανε η σομελιέ πριν ασχοληθεί με το κρασί επαγγελματικά;", ["Ήταν μαγείρισσα", "Δούλευε σε μια τράπεζα", "Ήταν φοιτήτρια στη Γαλλία", "Δούλευε στα αμπέλια της οικογένειας"], 1, "Σπούδασα όμως οικονομικά και δούλευα σε μια τράπεζα"),
  Q("Τι θεωρεί δουλειά της;", ["Να πουλάει το πιο ακριβό κρασί", "Να βρίσκει το κρασί που ταιριάζει στο φαγητό και στο γούστο του πελάτη", "Να σερβίρει μόνο γαλλικά κρασιά", "Να γράφει τον κατάλογο"], 1, "να βρω αυτό που ταιριάζει στο φαγητό και στο γούστο τους"),
  Q("Ποιο είναι, κατά τη σομελιέ, το καλύτερο κρασί;", ["Το πιο παλιό", "Αυτό που πίνεις με καλή παρέα", "Το ασύρτικο", "Το πιο ακριβό"], 1, "το καλύτερο κρασί είναι αυτό που πίνεις με καλή παρέα"),
 ],
 "gloss": {"σομελιέ": "σομελιέ — sommelier", "επάγγελμα": "επάγγελμα — profession", "αμπέλια": "αμπέλι — vineyard", "βαρέλια": "βαρέλι — barrel", "τρύγου": "τρύγος — grape harvest", "κατάλογο των κρασιών": "κατάλογος κρασιών — wine list", "ντρέπονται": "ντρέπομαι — to be shy, embarrassed", "γούστο": "γούστο — taste", "ποικιλίες": "ποικιλία — (grape) variety", "ασύρτικο": "ασύρτικο — assyrtiko (white grape)"},
})

ITEMS.append({
 "id": "l44-mono-neuromythoi", "title": "Μύθοι για τον εγκέφαλο", "title_en": "Myths about the brain", "type": "monologue", "level": "C1",
 "context_el": "Θα ακούσετε μια νευροεπιστήμονα που μιλάει σε μια εκδήλωση για εκπαιδευτικούς σχετικά με διαδεδομένους μύθους για τον εγκέφαλο.",
 "script": [
  L("Νευροεπιστήμονας", "f", "Ας ξεκινήσουμε με μια ερώτηση: πόσοι από εσάς έχετε ακούσει ότι χρησιμοποιούμε μόνο το δέκα τοις εκατό του εγκεφάλου μας; Οι περισσότεροι, βλέπω. Πρόκειται για έναν από τους πιο ανθεκτικούς μύθους, παρότι δεν έχει καμία επιστημονική βάση. Οι απεικονιστικές μέθοδοι δείχνουν ότι, μέσα σε μια μέρα, ενεργοποιούνται σχεδόν όλες οι περιοχές του εγκεφάλου, ακόμα και στον ύπνο.", "Let's start with a question: how many of you have heard that we use only ten per cent of our brain? Most of you, I see. It's one of the most persistent myths, even though it has no scientific basis at all. Imaging methods show that, over a day, almost all regions of the brain are activated, even during sleep."),
  L("Νευροεπιστήμονας", "f", "Ένας δεύτερος μύθος, ιδιαίτερα δημοφιλής στον χώρο της εκπαίδευσης, είναι ότι οι άνθρωποι χωρίζονται σε «αριστεροεγκεφαλικούς», λογικούς και αναλυτικούς, και «δεξιοεγκεφαλικούς», δημιουργικούς και διαισθητικούς. Είναι αλήθεια ότι ορισμένες λειτουργίες, όπως μεγάλο μέρος της γλώσσας, εντοπίζονται κυρίως στο ένα ημισφαίριο. Δεν υπάρχει όμως καμία ένδειξη ότι κάποιοι άνθρωποι χρησιμοποιούν συστηματικά περισσότερο το ένα ημισφαίριο από το άλλο.", "A second myth, especially popular in education, is that people are divided into 'left-brained', logical and analytical, and 'right-brained', creative and intuitive. It's true that certain functions, such as a large part of language, are located mainly in one hemisphere. But there is no evidence whatsoever that some people systematically use one hemisphere more than the other."),
  L("Νευροεπιστήμονας", "f", "Ο τρίτος μύθος σάς αφορά άμεσα: ότι κάθε μαθητής έχει ένα «μαθησιακό στυλ», οπτικό, ακουστικό ή κιναισθητικό, και μαθαίνει καλύτερα όταν η διδασκαλία προσαρμόζεται σε αυτό. Οι μαθητές πράγματι έχουν προτιμήσεις. Όμως οι προσεκτικά σχεδιασμένες μελέτες δεν έχουν δείξει ότι η προσαρμογή της διδασκαλίας σε αυτές τις προτιμήσεις βελτιώνει τη μάθηση.", "The third myth concerns you directly: that each student has a 'learning style', visual, auditory or kinaesthetic, and learns better when teaching is adapted to it. Students do have preferences. But carefully designed studies have not shown that adapting teaching to these preferences improves learning."),
  L("Νευροεπιστήμονας", "f", "Γιατί επιβιώνουν αυτοί οι μύθοι; Εν μέρει επειδή είναι απλοί και κολακευτικοί: μας υπόσχονται ανεκμετάλλευτες δυνάμεις ή μας βεβαιώνουν ότι είμαστε μοναδικοί. Το πρόβλημα είναι ότι στρέφουν χρόνο και χρήματα μακριά από πρακτικές που πράγματι λειτουργούν, όπως η κατανεμημένη επανάληψη, η ανάκληση από μνήμης και ο επαρκής ύπνος.", "Why do these myths survive? Partly because they are simple and flattering: they promise us untapped powers or reassure us that we are unique. The problem is that they divert time and money away from practices that really work, such as spaced repetition, retrieval practice and enough sleep."),
 ],
 "questions": [
  Q("Τι δείχνουν οι απεικονιστικές μέθοδοι για τον μύθο του δέκα τοις εκατό;", ["Ότι ισχύει μόνο για τους ενήλικες", "Ότι μέσα σε μια μέρα ενεργοποιούνται σχεδόν όλες οι περιοχές του εγκεφάλου", "Ότι χρησιμοποιούμε το πενήντα τοις εκατό", "Ότι ο εγκέφαλος σταματά στον ύπνο"], 1, "μέσα σε μια μέρα, ενεργοποιούνται σχεδόν όλες οι περιοχές του εγκεφάλου, ακόμα και στον ύπνο"),
  Q("Τι ισχύει, κατά την ομιλήτρια, για τα δύο ημισφαίρια;", ["Οι δημιουργικοί άνθρωποι χρησιμοποιούν το δεξί", "Ορισμένες λειτουργίες εντοπίζονται κυρίως στο ένα, αλλά κανείς δεν χρησιμοποιεί συστηματικά περισσότερο το ένα", "Λειτουργούν εντελώς ανεξάρτητα", "Η γλώσσα βρίσκεται και στα δύο εξίσου"], 1, "Δεν υπάρχει όμως καμία ένδειξη ότι κάποιοι άνθρωποι χρησιμοποιούν συστηματικά περισσότερο το ένα ημισφαίριο από το άλλο"),
  Q("Τι έχουν δείξει οι μελέτες για τα «μαθησιακά στυλ»;", ["Ότι οι μαθητές δεν έχουν καμία προτίμηση", "Ότι η προσαρμογή της διδασκαλίας σε αυτά δεν βελτιώνει τη μάθηση", "Ότι οι οπτικοί μαθητές μαθαίνουν πιο γρήγορα", "Ότι ισχύουν μόνο για τα μικρά παιδιά"], 1, "δεν έχουν δείξει ότι η προσαρμογή της διδασκαλίας σε αυτές τις προτιμήσεις βελτιώνει τη μάθηση"),
  Q("Ποιο είναι, κατά την ομιλήτρια, το πρόβλημα με αυτούς τους μύθους;", ["Ότι προσβάλλουν τους μαθητές", "Ότι στρέφουν χρόνο και χρήματα μακριά από πρακτικές που λειτουργούν", "Ότι είναι πολύ περίπλοκοι", "Ότι τους πιστεύουν μόνο οι γονείς"], 1, "στρέφουν χρόνο και χρήματα μακριά από πρακτικές που πράγματι λειτουργούν"),
 ],
 "gloss": {"νευροεπιστήμονα": "νευροεπιστήμονας — neuroscientist", "εκπαιδευτικούς": "εκπαιδευτικός — teacher, educator", "ανθεκτικούς": "ανθεκτικός — persistent, resilient", "απεικονιστικές": "απεικονιστικός — imaging (adj.)", "αριστεροεγκεφαλικούς": "αριστεροεγκεφαλικός — left-brained", "διαισθητικούς": "διαισθητικός — intuitive", "εντοπίζονται": "εντοπίζομαι — to be located", "ημισφαίριο": "ημισφαίριο — hemisphere", "μαθησιακό": "μαθησιακός — learning (adj.)", "κιναισθητικό": "κιναισθητικός — kinaesthetic", "κολακευτικοί": "κολακευτικός — flattering", "ανεκμετάλλευτες": "ανεκμετάλλευτος — untapped", "κατανεμημένη επανάληψη": "κατανεμημένη επανάληψη — spaced repetition", "ανάκληση από μνήμης": "ανάκληση από μνήμης — retrieval practice", "επαρκής": "επαρκής — sufficient"},
})

ITEMS.append({
 "id": "l44-int-dikaioma-lithis", "title": "Το δικαίωμα στη λήθη", "title_en": "The right to be forgotten", "type": "interview", "level": "C1",
 "context_el": "Θα ακούσετε μια συνέντευξη με μια νομικό που ειδικεύεται στην προστασία των προσωπικών δεδομένων.",
 "script": [
  L("Δημοσιογράφος", "m", "Τι ακριβώς είναι το λεγόμενο «δικαίωμα στη λήθη»;", "What exactly is the so-called 'right to be forgotten'?"),
  L("Νομικός", "f", "Είναι το δικαίωμα ενός ανθρώπου να ζητήσει να διαγραφούν προσωπικές του πληροφορίες από το διαδίκτυο, ή τουλάχιστον να μην εμφανίζονται στα αποτελέσματα των μηχανών αναζήτησης, όταν αυτές οι πληροφορίες είναι παλιές, ανακριβείς ή δεν εξυπηρετούν πια κανέναν θεμιτό σκοπό. Στην Ευρώπη αναγνωρίστηκε με μια απόφαση του Δικαστηρίου της Ευρωπαϊκής Ένωσης το 2014 και στη συνέχεια κατοχυρώθηκε στον Γενικό Κανονισμό για την Προστασία Δεδομένων.", "It is a person's right to ask for personal information about them to be deleted from the internet, or at least not to appear in search engine results, when that information is old, inaccurate or no longer serves any legitimate purpose. In Europe it was recognised by a ruling of the Court of Justice of the European Union in 2014 and was then enshrined in the General Data Protection Regulation."),
  L("Δημοσιογράφος", "m", "Δεν υπάρχει κίνδυνος να χρησιμοποιηθεί για να «σβηστούν» ενοχλητικές αλήθειες, για παράδειγμα από πολιτικούς;", "Isn't there a risk of it being used to 'erase' inconvenient truths, by politicians for example?"),
  L("Νομικός", "f", "Ο κίνδυνος υπάρχει, και γι' αυτό το δικαίωμα δεν είναι απόλυτο. Κάθε αίτημα σταθμίζεται απέναντι στο δημόσιο συμφέρον και στην ελευθερία της πληροφόρησης. Ένας ιδιώτης που πριν από δεκαπέντε χρόνια χρεοκόπησε έχει ισχυρά επιχειρήματα για να ζητήσει να μην εμφανίζεται το όνομά του σε κάθε αναζήτηση. Ένας υπουργός που κατηγορήθηκε για διαφθορά, αντίθετα, δύσκολα θα δικαιωθεί, γιατί η πληροφορία αφορά τη δημόσια δράση του.", "The risk exists, and that's why the right is not absolute. Each request is weighed against the public interest and freedom of information. A private individual who went bankrupt fifteen years ago has strong arguments for asking that his name not appear in every search. A minister who was accused of corruption, by contrast, will hardly win, because the information concerns his public conduct."),
  L("Δημοσιογράφος", "m", "Και στην πράξη; Μπορεί πράγματι κάτι να ξεχαστεί στο διαδίκτυο;", "And in practice? Can something really be forgotten on the internet?"),
  L("Νομικός", "f", "Εδώ βρίσκεται το παράδοξο. Η διαγραφή από τις ευρωπαϊκές εκδόσεις μιας μηχανής αναζήτησης δεν σημαίνει ότι η πληροφορία εξαφανίζεται· μπορεί να υπάρχει σε αρχεία, σε άλλες χώρες ή σε στιγμιότυπα οθόνης που έχουν ήδη κυκλοφορήσει. Το δικαίωμα στη λήθη δεν υπόσχεται, λοιπόν, πραγματική λήθη, αλλά κάτι πιο ταπεινό: να γίνει μια πληροφορία πιο δυσεύρετη, ώστε να μην καθορίζει για πάντα πώς μας βλέπουν οι άλλοι.", "Here lies the paradox. Removal from the European versions of a search engine doesn't mean the information disappears; it may exist in archives, in other countries or in screenshots that have already circulated. So the right to be forgotten does not promise real forgetting, but something more modest: to make a piece of information harder to find, so that it doesn't determine forever how others see us."),
 ],
 "questions": [
  Q("Πότε μπορεί κάποιος να ζητήσει να διαγραφούν πληροφορίες για τον ίδιο;", ["Όποτε θέλει, χωρίς προϋποθέσεις", "Όταν είναι παλιές, ανακριβείς ή δεν εξυπηρετούν πια θεμιτό σκοπό", "Μόνο αν είναι πολιτικός", "Μόνο αν η πληροφορία είναι ψεύτικη"], 1, "όταν αυτές οι πληροφορίες είναι παλιές, ανακριβείς ή δεν εξυπηρετούν πια κανέναν θεμιτό σκοπό"),
  Q("Πώς αναγνωρίστηκε το δικαίωμα στην Ευρώπη;", ["Με δημοψήφισμα", "Με απόφαση του Δικαστηρίου της Ευρωπαϊκής Ένωσης το 2014", "Με έναν ελληνικό νόμο", "Με συμφωνία των μηχανών αναζήτησης"], 1, "αναγνωρίστηκε με μια απόφαση του Δικαστηρίου της Ευρωπαϊκής Ένωσης το 2014"),
  Q("Γιατί ένας υπουργός που κατηγορήθηκε για διαφθορά δύσκολα θα δικαιωθεί;", ["Επειδή δεν έχει δικηγόρο", "Επειδή η πληροφορία αφορά τη δημόσια δράση του", "Επειδή το αίτημα κοστίζει πολύ", "Επειδή οι υπουργοί δεν έχουν προσωπικά δεδομένα"], 1, "η πληροφορία αφορά τη δημόσια δράση του"),
  Q("Τι υπόσχεται τελικά, κατά τη νομικό, το δικαίωμα στη λήθη;", ["Την οριστική εξαφάνιση κάθε πληροφορίας", "Να γίνει μια πληροφορία πιο δυσεύρετη", "Την τιμωρία όσων δημοσίευσαν την πληροφορία", "Αποζημίωση για τον ενδιαφερόμενο"], 1, "να γίνει μια πληροφορία πιο δυσεύρετη, ώστε να μην καθορίζει για πάντα πώς μας βλέπουν οι άλλοι"),
 ],
 "gloss": {"νομικό": "νομικός — lawyer, legal expert", "προσωπικών δεδομένων": "προσωπικά δεδομένα — personal data", "λήθη": "λήθη — oblivion, forgetting", "να διαγραφούν": "διαγράφομαι — to be deleted", "μηχανών αναζήτησης": "μηχανή αναζήτησης — search engine", "ανακριβείς": "ανακριβής — inaccurate", "θεμιτό": "θεμιτός — legitimate", "κατοχυρώθηκε": "κατοχυρώνομαι — to be enshrined, secured", "σταθμίζεται": "σταθμίζομαι — to be weighed", "δημόσιο συμφέρον": "δημόσιο συμφέρον — public interest", "χρεοκόπησε": "χρεοκοπώ — to go bankrupt", "διαφθορά": "διαφθορά — corruption", "δικαιωθεί": "δικαιώνομαι — to be vindicated, win one's case", "στιγμιότυπα οθόνης": "στιγμιότυπο οθόνης — screenshot", "δυσεύρετη": "δυσεύρετος — hard to find"},
})

rnd = random.Random(44)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
with open(os.path.join(root, "library", "listening", "listening-44.json"), "w", encoding="utf-8") as fh:
    json.dump({"items": ITEMS}, fh, ensure_ascii=False, indent=1); fh.write("\n")
print(len(ITEMS), "items,", sum(len(i["questions"]) for i in ITEMS), "questions")
